ALTER TABLE orders ADD COLUMN scheduled_at INTEGER;
ALTER TABLE orders ADD COLUMN preparation_due_at INTEGER;
ALTER TABLE orders ADD COLUMN car_description TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN arrived_at INTEGER;
ALTER TABLE settings ADD COLUMN slot_capacity INTEGER NOT NULL DEFAULT 8;
ALTER TABLE settings ADD COLUMN schedule_days INTEGER NOT NULL DEFAULT 7;
ALTER TABLE products ADD COLUMN available_from INTEGER;
ALTER TABLE products ADD COLUMN available_until INTEGER;
ALTER TABLE products ADD COLUMN featured INTEGER NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN seasonal_label TEXT NOT NULL DEFAULT '';
CREATE TABLE branch_hours(branch_id TEXT NOT NULL REFERENCES branches(id),weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),opening_minute INTEGER NOT NULL CHECK(opening_minute BETWEEN 0 AND 1439),closing_minute INTEGER NOT NULL CHECK(closing_minute BETWEEN 1 AND 1440),closed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(branch_id,weekday));
CREATE INDEX orders_schedule ON orders(branch_id,scheduled_at,status);
CREATE TRIGGER royal_slot_capacity BEFORE INSERT ON orders WHEN NEW.scheduled_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.id) BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM orders WHERE branch_id=NEW.branch_id AND scheduled_at=NEW.scheduled_at AND status!='cancelled')>=(SELECT slot_capacity FROM settings WHERE id=1) THEN RAISE(ABORT,'slot_full') END; END;
CREATE TRIGGER royal_product_availability BEFORE INSERT ON orders WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.id) BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.items) j LEFT JOIN products p ON p.id=json_extract(j.value,'$.id') WHERE p.id IS NULL OR p.available=0 OR (p.available_from IS NOT NULL AND p.available_from>CAST(strftime('%s','now') AS INTEGER)) OR (p.available_until IS NOT NULL AND p.available_until<=CAST(strftime('%s','now') AS INTEGER))) THEN RAISE(ABORT,'product_unavailable') END; END;
CREATE TABLE order_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,kind TEXT NOT NULL,status TEXT NOT NULL,message TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL);
CREATE INDEX order_events_order ON order_events(order_id,seq);
CREATE TRIGGER royal_order_created_event AFTER INSERT ON orders BEGIN INSERT INTO order_events(order_id,kind,status,created_at) VALUES(NEW.id,'created',NEW.status,NEW.created_at); END;
CREATE TRIGGER royal_order_status_event AFTER UPDATE OF status ON orders WHEN OLD.status!=NEW.status BEGIN INSERT INTO order_events(order_id,kind,status,created_at) VALUES(NEW.id,'status',NEW.status,CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER royal_order_message_event AFTER INSERT ON order_messages BEGIN INSERT INTO order_events(order_id,kind,status,message,created_at) SELECT NEW.order_id,'message',status,NEW.text,NEW.created_at FROM orders WHERE id=NEW.order_id; END;
CREATE TABLE customer_activity_read(customer_id TEXT PRIMARY KEY REFERENCES customers(id) ON DELETE CASCADE,last_seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE customer_statistics(customer_id TEXT PRIMARY KEY REFERENCES customers(id) ON DELETE CASCADE,delivered_orders INTEGER NOT NULL DEFAULT 0,delivered_drinks INTEGER NOT NULL DEFAULT 0);
INSERT INTO customer_statistics SELECT customer_id,COUNT(*),SUM((SELECT SUM(json_extract(value,'$.quantity')) FROM json_each(items))) FROM orders WHERE status='delivered' AND customer_id IS NOT NULL GROUP BY customer_id;
CREATE TRIGGER royal_customer_delivered AFTER UPDATE OF status ON orders WHEN NEW.status='delivered' AND OLD.status!='delivered' AND NEW.customer_id IS NOT NULL BEGIN INSERT INTO customer_statistics VALUES(NEW.customer_id,1,(SELECT SUM(json_extract(value,'$.quantity')) FROM json_each(NEW.items))) ON CONFLICT(customer_id) DO UPDATE SET delivered_orders=delivered_orders+1,delivered_drinks=delivered_drinks+excluded.delivered_drinks; END;
CREATE TRIGGER royal_customer_claim_delivered AFTER UPDATE OF customer_id ON orders WHEN OLD.customer_id IS NULL AND NEW.customer_id IS NOT NULL AND NEW.status='delivered' BEGIN INSERT INTO customer_statistics VALUES(NEW.customer_id,1,(SELECT SUM(json_extract(value,'$.quantity')) FROM json_each(NEW.items))) ON CONFLICT(customer_id) DO UPDATE SET delivered_orders=delivered_orders+1,delivered_drinks=delivered_drinks+excluded.delivered_drinks; END;
